MODELAGEM_LOGICO_ALGORITMA.CODIGO_FONTE:
void mostrarJogada() {
  if (primeiroSorteio) {
    randomSeed(micros());
    primeiroSorteio = false;
  }
  byte escolha = random(3);
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print(respostas[escolha]);
  Serial.print("Jogada: ");
  Serial.println(respostas[escolha]);
  delay(tempoResposta);
  mostrarConvite();
}
